function renderCondition(){
 conditionPreviewUrls.forEach(url=>URL.revokeObjectURL(url));conditionPreviewUrls=[];
 for(const phase of ['move-in','move-out']){
  const root=$(phase==='move-in'?'#moveInGallery':'#moveOutGallery'),records=state.condition.filter(p=>p.phase===phase);
  if(!records.length){root.className='gallery empty-state';root.textContent=`No ${phase} evidence yet.`;continue}
  root.className='gallery';root.innerHTML=records.map(p=>`<article class="gallery-card" data-condition-id="${esc(p.id)}"><div><strong>${esc(p.room)}</strong><small>${phase==='move-in'?'Move-in':'Move-out'} · ${esc(p.date)}</small><small class="condition-notes">${esc(p.notes)}</small><div class="condition-image-slot property-photos"></div><div class="property-actions"><button type="button" class="ghost compact" data-add-condition-photos="${esc(p.id)}">Add photos</button><button type="button" class="ghost compact" data-edit-condition-id="${esc(p.id)}">Edit</button><button type="button" class="ghost compact" data-remove-condition-id="${esc(p.id)}">Delete record</button></div></div></article>`).join('');
  for(const p of records){const slot=root.querySelector(`[data-condition-id="${CSS.escape(p.id)}"] .condition-image-slot`);for(const id of propertyAttachmentIds(p)){
   if(window.CloudLedger?.active()){window.CloudLedger.mountImage(slot,id,p.room);continue;}
   (async()=>{const a=await attachmentGet(id).catch(()=>null);if(!a?.blob||!slot.isConnected)return;const url=URL.createObjectURL(a.blob);conditionPreviewUrls.push(url);const image=document.createElement('img');image.className='attachment-thumb';image.src=url;image.alt=p.room;slot.append(image)})();
  }if(validImageSource(p.data)){const image=document.createElement('img');image.className='attachment-thumb';image.src=p.data;image.alt=p.room;slot.append(image)}}
 }
}
