function ensureSyncMeta(){state.syncMeta=state.syncMeta||{deviceId:crypto.randomUUID(),tombstones:[],settingsUpdatedAt:new Date().toISOString(),pending:false};state.syncMeta.deviceId=state.syncMeta.deviceId||crypto.randomUUID();state.syncMeta.tombstones=Array.isArray(state.syncMeta.tombstones)?state.syncMeta.tombstones:[];return state.syncMeta}
