function markSyncDirty(){const meta=ensureSyncMeta(),now=new Date().toISOString();for(const record of [...state.transactions,...state.condition]){record._sync=record._sync||{createdAt:now,updatedAt:now};const hash=syncHash(record);if(meta.lastHashes?.[record.id]&&meta.lastHashes[record.id]!==hash)record._sync.updatedAt=now;meta.lastHashes=meta.lastHashes||{};meta.lastHashes[record.id]=syncHash(record)}meta.settingsHash=meta.settingsHash||syncHash(syncSettingsSnapshot());if(meta.settingsHash!==syncHash(syncSettingsSnapshot())){meta.settingsUpdatedAt=now;meta.settingsHash=syncHash(syncSettingsSnapshot())}meta.pending=true}
