function mergeSyncRecords(local=[],remote=[],tombstones=[]){const byId=new Map(local.filter(r=>r?.id).map(r=>[r.id,r])),conflicts=[];for(const record of remote.filter(r=>r?.id)){const prior=byId.get(record.id),localTime=syncUpdatedAt(prior),remoteTime=syncUpdatedAt(record);if(!prior||remoteTime>localTime)byId.set(record.id,record);else if(remoteTime===localTime&&syncHash(prior)!==syncHash(record))conflicts.push(record.id)}const dead=new Map(tombstones.filter(t=>t?.id).map(t=>[t.id,syncUpdatedAt(t)]));return{records:[...byId.values()].filter(record=>syncUpdatedAt(record)>=(dead.get(record.id)||-1)&&!(dead.has(record.id)&&dead.get(record.id)>syncUpdatedAt(record))),conflicts}}
function syncStatusText(){const s=state.settings.googleSync||DEFAULT_SETTINGS.googleSync;if(!navigator.onLine)return'Offline · local changes remain queued for sync';if(s.status==='syncing')return'Syncing with private Google storage…';if(s.status==='synced')return`Synced${s.accountEmail?` · ${s.accountEmail}`:''}`;if(s.status==='error')return`Sync error · ${s.lastError||'Try again'}`;if(s.status==='conflict')return`Synced with ${s.conflictCount||0} local conflict${s.conflictCount===1?'':'s'} preserved`;return'Google not connected · local data remains available offline.'}
function renderSync(){const s=state.settings.googleSync||DEFAULT_SETTINGS.googleSync;if($('#googleClientIdInput'))$('#googleClientIdInput').value=s.clientId||'';if($('#syncStatus'))$('#syncStatus').textContent=syncStatusText();if($('#syncLastSuccess'))$('#syncLastSuccess').textContent=s.lastSuccessAt?`Last successful sync: ${new Date(s.lastSuccessAt).toLocaleString()}`:'No successful sync yet.'}
const renderWithSync=render;render=()=>{renderWithSync();renderSync()};ensureSyncMeta();
function loadGoogleIdentity(){return new Promise((resolve,reject)=>{if(window.google?.accounts?.oauth2)return resolve();const script=document.createElement('script');script.src='https://accounts.google.com/gsi/client';script.onload=resolve;script.onerror=()=>reject(new Error('Google Identity Services failed to load'));document.head.append(script)})}
async function requestGoogleToken(interactive=true){if(googleToken&&Date.now()<googleTokenExpiresAt-30000)return googleToken;const clientId=state.settings.googleSync.clientId.trim();if(!clientId)throw new Error('Enter a Google OAuth web client ID in Settings first.');await loadGoogleIdentity();return new Promise((resolve,reject)=>{googleTokenClient=google.accounts.oauth2.initTokenClient({client_id:clientId,scope:GOOGLE_SCOPE,callback:async response=>{if(response.error)return reject(new Error(response.error));googleToken=response.access_token;googleTokenExpiresAt=Date.now()+Number(response.expires_in||3600)*1000;sessionStorage.setItem(SYNC_SESSION_TOKEN,googleToken);sessionStorage.setItem(SYNC_SESSION_EXPIRY,String(googleTokenExpiresAt));try{const identity=await fetch('https://openidconnect.googleapis.com/v1/userinfo',{headers:{Authorization:`Bearer ${googleToken}`}}).then(r=>r.ok?r.json():null);if(identity?.email)state.settings.googleSync.accountEmail=identity.email}catch{}resolve(googleToken)}});googleTokenClient.requestAccessToken({prompt:interactive?'consent':''})})}
async function googleFetch(url,options={}){const token=await requestGoogleToken(false);const response=await fetch(url,{...options,headers:{...(options.headers||{}),Authorization:`Bearer ${token}`}});if(response.status===401){googleToken=null;sessionStorage.removeItem(SYNC_SESSION_TOKEN);throw new Error('Google authorization expired. Connect again.')}if(!response.ok)throw new Error(`Google request failed (${response.status})`);return response}
async function findRemoteSyncFile(){const query=encodeURIComponent(`name='${SYNC_FILE_NAME}' and trashed=false`),response=await googleFetch(`https://www.googleapis.com/drive/v3/files?spaces=appDataFolder&q=${query}&fields=files(id,name,modifiedTime)&pageSize=10`);return (await response.json()).files?.[0]||null}
async function readRemoteSync(file){return googleFetch(`https://www.googleapis.com/drive/v3/files/${file.id}?alt=media`).then(r=>r.json())}
async function writeRemoteSync(payload,file){const body=JSON.stringify(payload);if(file)return googleFetch(`https://www.googleapis.com/upload/drive/v3/files/${file.id}?uploadType=media&fields=id,name,modifiedTime`,{method:'PATCH',headers:{'Content-Type':'application/json'},body}).then(r=>r.json());const boundary=`50aLedgerBoundary${Date.now()}`,multipart=new Blob([`--${boundary}\r\nContent-Type: application/json; charset=UTF-8\r\n\r\n${JSON.stringify({name:SYNC_FILE_NAME,parents:['appDataFolder']})}\r\n--${boundary}\r\nContent-Type: application/json\r\n\r\n${body}\r\n--${boundary}--`],{type:`multipart/related; boundary=${boundary}`});return googleFetch('https://www.googleapis.com/upload/drive/v3/files?uploadType=multipart&fields=id,name,modifiedTime',{method:'POST',headers:{'Content-Type':`multipart/related; boundary=${boundary}`},body:multipart}).then(r=>r.json())}
function validateSyncPayload(payload){if(!payload||payload.format!=='50a-ledger-sync'||payload.schemaVersion!==SYNC_SCHEMA_VERSION||!payload.state||!Array.isArray(payload.state.transactions)||!Array.isArray(payload.state.condition))throw new Error('Unsupported or invalid Google sync data. Local data was not changed.');return payload}
function applyRemoteMerge(remote){validateSyncPayload(remote);const mergedTx=mergeSyncRecords(state.transactions,remote.state.transactions,[...(state.syncMeta.tombstones||[]),...(remote.tombstones||[])]),mergedCondition=mergeSyncRecords(state.condition,remote.state.condition,[...(state.syncMeta.tombstones||[]),...(remote.tombstones||[])]);state.transactions=normalizeTransactions(mergedTx.records);state.condition=mergedCondition.records;const localSettingsTime=new Date(state.syncMeta.settingsUpdatedAt||0).getTime(),remoteSettingsTime=new Date(remote.settingsUpdatedAt||remote.updatedAt||0).getTime();if(remoteSettingsTime>localSettingsTime)state.settings={...state.settings,...normalizeSettings(remote.state.settings),googleSync:state.settings.googleSync};state.budget=remoteSettingsTime>localSettingsTime?Number(remote.state.budget??state.budget):state.budget;state.syncMeta.tombstones=[...(state.syncMeta.tombstones||[]),...(remote.tombstones||[])].filter((item,index,array)=>item?.id&&array.findIndex(x=>x.id===item.id)===index);const mergedBills=mergeSyncRecords(state.recurringCharges,remote.state.recurringCharges||[]);state.recurringCharges=mergedBills.records;const conflicts=[...mergedTx.conflicts,...mergedCondition.conflicts,...mergedBills.conflicts];state.settings.googleSync.conflictCount=conflicts.length;return conflicts}
async function syncNow(interactive=true){if(window.CloudLedger?.active())return;const gs=state.settings.googleSync;try{if(!navigator.onLine){gs.status='offline';gs.lastError=null;save();return}gs.status='syncing';renderSync();await requestGoogleToken(interactive);const remoteFile=await findRemoteSyncFile(),localPayload=buildSyncPayload();if(!remoteFile){await writeRemoteSync(localPayload);gs.status='synced';gs.lastSuccessAt=new Date().toISOString();gs.lastError=null;state.syncMeta.pending=false;save();return}const remote=validateSyncPayload(await readRemoteSync(remoteFile));const conflicts=applyRemoteMerge(remote);const merged=buildSyncPayload();await writeRemoteSync(merged,remoteFile);gs.status=conflicts.length?'conflict':'synced';gs.lastSuccessAt=new Date().toISOString();gs.lastError=null;state.syncMeta.pending=false;save()}catch(error){gs.status=navigator.onLine?'error':'offline';gs.lastError=error.message;save()}}
async function connectGoogle(){state.settings.googleSync.clientId=$('#googleClientIdInput').value.trim();state.settings.googleSync.status='syncing';save();await syncNow(true)}
async function restoreGoogle(){if(window.CloudLedger?.active())return;if(!confirm('Merge the private Google Ledger backup into this device? Local records with newer timestamps will be preserved.'))return;await syncNow(true)}
function disconnectGoogle(){googleToken=null;googleTokenClient=null;googleTokenExpiresAt=0;sessionStorage.removeItem(SYNC_SESSION_TOKEN);sessionStorage.removeItem(SYNC_SESSION_EXPIRY);state.settings.googleSync={...DEFAULT_SETTINGS.googleSync,clientId:state.settings.googleSync.clientId};save()}
$('#connectGoogleBtn').onclick=connectGoogle;$('#syncNowBtn').onclick=()=>syncNow(true);$('#restoreGoogleBtn').onclick=restoreGoogle;$('#disconnectGoogleBtn').onclick=disconnectGoogle;window.addEventListener('online',()=>{if(state.settings.googleSync.clientId&&(state.settings.googleSync.status==='offline'||state.syncMeta?.pending))syncNow(false)});window.addEventListener('offline',()=>{state.settings.googleSync.status='offline';renderSync()});

// Data-layer functions can also be called by a future non-UI entry point.
function saveRecurringCharge(input){state.recurringCharges=RecurringUtils.upsert(state.recurringCharges,input);save()}
function deactivateRecurringCharge(id){state.recurringCharges=RecurringUtils.deactivate(state.recurringCharges,id);save()}
function renderRecurringCharges(){
  $('#billsTotal').textContent=money(RecurringUtils.total(state.recurringCharges));
  $('#recurringList').innerHTML=(state.recurringCharges||[]).map(bill=>`<article class="transaction-card"><div class="transaction-top"><div><h3>${esc(bill.name)}</h3><p class="meta">${esc(bill.category)} · ${bill.kind==='estimated'?'Variable / estimated':'Fixed'}${bill.active===false?' · Inactive':''}</p><strong>${money(bill.amount)} / month</strong></div><div class="transaction-actions"><button class="ghost" data-edit-bill="${esc(bill.id)}">Edit</button>${bill.active!==false?`<button class="ghost" data-deactivate-bill="${esc(bill.id)}">Deactivate</button>`:''}</div></div></article>`).join('')||'<p class="empty-state">No monthly bills yet. Add the ongoing service amount, excluding setup fees.</p>';
}
let editingBillId=null;
const billDialog=$('#billDialog'),billForm=$('#billForm');
function openBill(id){
  const bill=state.recurringCharges.find(record=>record.id===id);editingBillId=bill?.id||null;billForm.reset();
  $('#billDialogTitle').textContent=bill?'Edit monthly bill':'Add monthly bill';
  if(bill)for(const key of ['name','amount','category','kind','utilityType'])billForm.elements[key].value=bill[key]??'';
  billForm.elements.active.checked=bill?.active!==false;$('#billError').textContent='';billDialog.showModal();
}
$('#addBillBtn').onclick=()=>openBill();$('#cancelBillBtn').onclick=()=>billDialog.close();
$('#recurringList').addEventListener('click',event=>{const edit=event.target.closest('[data-edit-bill]'),remove=event.target.closest('[data-deactivate-bill]');if(edit)openBill(edit.dataset.editBill);if(remove)deactivateRecurringCharge(remove.dataset.deactivateBill)});
billForm.addEventListener('submit',event=>{event.preventDefault();try{saveRecurringCharge({...Object.fromEntries(new FormData(billForm)),id:editingBillId,active:billForm.elements.active.checked});billDialog.close()}catch(error){$('#billError').textContent=error.message}});

